// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(address recipient, uint256 amount, uint256 priorCalls) public {
        vm.assume(recipient != address(0));
        amount = bound(amount, 0, type(uint128).max);
        priorCalls = bound(priorCalls, 0, 10);

        // Establish an arbitrary (fuzzed) prior state of the proposal counter.
        for (uint256 i = 0; i < priorCalls; i++) {
            c.newGrantProposal(recipient, amount);
        }
        uint256 before = c.proposalCount();

        c.newGrantProposal(recipient, amount);

        // General rule: a grant proposal advances the counter by exactly 1.
        assertTrue(c.proposalCount() == before + 1, "proposal counter must advance by exactly one per grant proposal");
    }
}
